<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Access\User\Domain\ValueObject\Holder\UserApproveAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserApproveAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class UserApproveAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getApprove returns null on a freshly created holder.
     */
    public function testApproveNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithUserApproveAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isApproveAssigned());
        $this->assertNull($holder->getApprove());
    }
}
class ImplWithUserApproveAttributeHolderUnitTest
{
    use UserApproveAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedApproveRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultApprove();
    }
}
